-- Business tables from the local workerd PersonalAccount fixture. No account data.
CREATE TABLE IF NOT EXISTS assistants (id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS call_failures (
    id TEXT PRIMARY KEY, createdAt INTEGER NOT NULL, code TEXT NOT NULL, upstreamStatus INTEGER);
CREATE TABLE IF NOT EXISTS channels (id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS claw_agents (pluginId TEXT PRIMARY KEY, agents TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS claw_connectors (pluginId TEXT PRIMARY KEY, tokenHash TEXT NOT NULL, lastSeen INTEGER NOT NULL DEFAULT 0, nativeCommands INTEGER NOT NULL DEFAULT 0, connectorVersion TEXT NOT NULL DEFAULT '', versionSeenAt INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS claw_events (id TEXT PRIMARY KEY, pluginId TEXT NOT NULL, receipt TEXT NOT NULL, createdAt INTEGER NOT NULL, sessionId TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS claw_jobs (id TEXT PRIMARY KEY, routeId TEXT NOT NULL, pluginId TEXT NOT NULL, text TEXT NOT NULL, state TEXT NOT NULL, createdAt INTEGER NOT NULL, inputTokens INTEGER NOT NULL, outputLimit INTEGER NOT NULL, runnerId TEXT NOT NULL DEFAULT '', command TEXT NOT NULL DEFAULT '', lane TEXT NOT NULL DEFAULT 'message');
CREATE TABLE IF NOT EXISTS claw_pairings (pluginId TEXT PRIMARY KEY, secretHash TEXT NOT NULL, expiresAt INTEGER NOT NULL, claimHash TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS claw_routes (id TEXT PRIMARY KEY, pluginId TEXT NOT NULL, sessionId TEXT NOT NULL, connectionId TEXT NOT NULL, generation TEXT NOT NULL, epoch INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS cloud_callbacks (
        deliveryId TEXT PRIMARY KEY, taskId TEXT NOT NULL, jobId TEXT NOT NULL,
        hash TEXT NOT NULL, createdAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS cloud_provision (
        id INTEGER PRIMARY KEY CHECK(id = 1), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cloud_task_images (
        taskId TEXT NOT NULL, imageId TEXT NOT NULL, part INTEGER NOT NULL,
        data BLOB NOT NULL, PRIMARY KEY(taskId,imageId,part));
CREATE TABLE IF NOT EXISTS cloud_tasks (
        id TEXT PRIMARY KEY, pluginId TEXT NOT NULL, sessionId TEXT NOT NULL,
        connectionId TEXT NOT NULL, state TEXT NOT NULL, jobId TEXT NOT NULL DEFAULT '',
        createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, deadline INTEGER NOT NULL,
        nextAt INTEGER NOT NULL, stopRequested INTEGER NOT NULL DEFAULT 0,
        settled INTEGER NOT NULL DEFAULT 0, stale INTEGER NOT NULL DEFAULT 0,
        delivered INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS context_summaries (sessionId TEXT PRIMARY KEY, text TEXT NOT NULL, throughId INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS execution_data(id TEXT NOT NULL,kind TEXT NOT NULL,part INTEGER NOT NULL,data BLOB NOT NULL,PRIMARY KEY(id,kind,part));
CREATE TABLE IF NOT EXISTS execution_jobs(id TEXT PRIMARY KEY,runId TEXT NOT NULL,state TEXT NOT NULL,lease TEXT NOT NULL DEFAULT '',expiresAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS execution_registry(id INTEGER PRIMARY KEY CHECK(id=1),dirty INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS execution_turns(id TEXT PRIMARY KEY, connectionId TEXT NOT NULL, generation TEXT NOT NULL, startedAt INTEGER NOT NULL, deadline INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS inbox (id TEXT PRIMARY KEY, payload TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', reply TEXT NOT NULL DEFAULT '', part INTEGER NOT NULL DEFAULT 0, attempts INTEGER NOT NULL DEFAULT 0, createdAt INTEGER NOT NULL, sessionId TEXT, connectionId TEXT NOT NULL DEFAULT 'default');
CREATE TABLE IF NOT EXISTS membership_reminders (id INTEGER PRIMARY KEY CHECK(id=1), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages (id INTEGER PRIMARY KEY AUTOINCREMENT, sessionId TEXT NOT NULL, role TEXT NOT NULL, content TEXT NOT NULL, createdAt INTEGER NOT NULL, inputTokens INTEGER NOT NULL DEFAULT 0, outputTokens INTEGER NOT NULL DEFAULT 0, cost REAL NOT NULL DEFAULT 0, estimated INTEGER NOT NULL DEFAULT 0, model TEXT NOT NULL DEFAULT '', displayContent TEXT);
CREATE TABLE IF NOT EXISTS notification_jobs (
        id TEXT PRIMARY KEY, pluginId TEXT NOT NULL, dedupe TEXT NOT NULL, fingerprint TEXT NOT NULL,
        connectionId TEXT NOT NULL, generation TEXT NOT NULL, title TEXT NOT NULL, text TEXT NOT NULL,
        state TEXT NOT NULL, createdAt INTEGER NOT NULL, sentAt INTEGER, attempts INTEGER NOT NULL DEFAULT 0,
        nextAt INTEGER NOT NULL, error TEXT NOT NULL DEFAULT '', UNIQUE(pluginId,dedupe));
CREATE TABLE IF NOT EXISTS notification_schedule (id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL, acknowledged INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS notification_tokens (pluginId TEXT PRIMARY KEY, hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS output_assets (id TEXT PRIMARY KEY, runId TEXT NOT NULL, sessionId TEXT, mime TEXT NOT NULL, bytes INTEGER NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, expiresAt INTEGER NOT NULL, committed INTEGER NOT NULL DEFAULT 0, wechat TEXT NOT NULL DEFAULT '', name TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS pending_attachments (
      connectionId TEXT PRIMARY KEY, sessionId TEXT NOT NULL, generation TEXT NOT NULL,
      contextStart INTEGER NOT NULL, token TEXT NOT NULL, items TEXT NOT NULL, expiresAt INTEGER NOT NULL
    );
CREATE TABLE IF NOT EXISTS personal_record_migrations (version INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS personal_record_state (
          pluginId TEXT NOT NULL, connectionId TEXT NOT NULL DEFAULT '',
          revision INTEGER NOT NULL, changes TEXT NOT NULL, PRIMARY KEY(pluginId,connectionId)
        );
CREATE TABLE IF NOT EXISTS personal_records (id TEXT PRIMARY KEY, pluginId TEXT NOT NULL, revision INTEGER NOT NULL, kind TEXT NOT NULL, date TEXT NOT NULL, amountCents INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, connectionId TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS personal_reminder_schedule (id INTEGER PRIMARY KEY CHECK (id=1), revision INTEGER NOT NULL, acknowledged INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS personal_reminders (id TEXT PRIMARY KEY, pluginId TEXT NOT NULL, recordId TEXT NOT NULL UNIQUE, revision INTEGER NOT NULL, dueAt INTEGER NOT NULL, repeatMs INTEGER NOT NULL, connectionId TEXT NOT NULL, generation TEXT NOT NULL, state TEXT NOT NULL, retryAt INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, error TEXT NOT NULL DEFAULT '', recordConnectionId TEXT NOT NULL DEFAULT '', lastFailure TEXT, errorDueAt INTEGER, blockReason TEXT);
CREATE TABLE IF NOT EXISTS personal_run_data (id TEXT NOT NULL, kind TEXT NOT NULL, part INTEGER NOT NULL, data BLOB NOT NULL, PRIMARY KEY(id,kind,part));
CREATE TABLE IF NOT EXISTS personal_runs (id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS plugins (id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runs (id TEXT PRIMARY KEY, sessionId TEXT, status TEXT NOT NULL, response TEXT NOT NULL DEFAULT '', createdAt INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS usage (id TEXT PRIMARY KEY, createdAt INTEGER NOT NULL, tokens INTEGER NOT NULL, units INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS wechat_links (id TEXT PRIMARY KEY, name TEXT NOT NULL, createdAt INTEGER NOT NULL);
